1	-- Banks without transaction IDs repeat rows on every overlapping sync. A bank's answer is complete for the dates it
2	-- covers, so identical rows can be compared by how many there are: n identical rows the bank states against n canonical
3	-- ledger rows are repeats, and one more is a genuine second payment. mapping.completeWindow marks an import that came
4	-- from such an answer; a file has no such promise, so its overlaps still go to review.
5	create or replace function public.import_batch_candidates(p_import_id uuid,p_workspace_id uuid,p_run_version integer,p_offset integer) returns jsonb
6	language plpgsql security definer set search_path='' as $$
7	declare total integer; item jsonb; candidates jsonb; result jsonb:='[]'::jsonb; occurrences jsonb:='{}'::jsonb;
8	begin
9	  total:=public.read_import_stage(p_import_id,p_workspace_id,p_run_version);
10	  if total is null or p_offset is null or p_offset<0 or p_offset%250<>0 or p_offset>=total then raise exception 'Invalid normalized batch offset' using errcode='22023'; end if;
11	  if (select (mapping->>'completeWindow')::boolean from public.imports where id=p_import_id) then
12	    select coalesce(jsonb_object_agg(rank.row_number,jsonb_build_object('index',rank.position,'total',rank.identical)),'{}'::jsonb) into occurrences from (
13	      select r.value->'row'->>'rowNumber' row_number,
14	        row_number() over identical position, count(*) over identical identical
15	      from public.import_staging s,jsonb_array_elements(s.rows) r
16	      where s.import_id=p_import_id and not (r.value->>'excluded')::boolean and r.value->'row'->>'externalId' is null
17	      window identical as (partition by r.value->>'accountId',r.value->'row'->>'currencyCode',r.value->'row'->>'postedOn',r.value->'row'->>'amountMinor',r.value->'row'->>'description' order by (r.value->'row'->>'rowNumber')::integer rows between unbounded preceding and unbounded following)
18	    ) rank;
19	  end if;
20	  for item in select value from public.import_staging s,jsonb_array_elements(s.rows) with ordinality r(value,n) where s.import_id=p_import_id and n>p_offset and n<=p_offset+250 loop
21	    if (item->>'excluded')::boolean then continue; end if;
22	    select coalesce(jsonb_agg(candidate),'[]'::jsonb) into candidates from (
23	      -- Separate equality paths let PostgreSQL use each candidate index. An
24	      -- OR with a correlated source lookup otherwise scans all account history
25	      -- for every row once PL/pgSQL chooses a generic cached plan.
26	      select distinct candidate from (
27	        select jsonb_build_object('id',t.id,'status',t.status,'version',t.version,
28	          'stableExternalMatch',coalesce(src.external_id=item->'row'->>'externalId',false)) candidate
29	        from public.transactions t
30	        left join public.transaction_sources link on link.transaction_id=t.id
31	        left join public.source_transactions src on src.id=link.source_transaction_id
32	        where t.workspace_id=p_workspace_id and t.account_id=(item->>'accountId')::uuid and t.currency_code=item->'row'->>'currencyCode'
33	          and t.posted_on=(item->'row'->>'postedOn')::date and t.amount_minor=(item->'row'->>'amountMinor')::bigint and t.description=item->'row'->>'description'
34	          and (src.id is null or (src.workspace_id=p_workspace_id and src.import_id<>p_import_id))
35	        union all
36	        select jsonb_build_object('id',t.id,'status',t.status,'version',t.version,
37	          'stableExternalMatch',t.posted_on=(item->'row'->>'postedOn')::date and t.amount_minor=(item->'row'->>'amountMinor')::bigint and t.description=item->'row'->>'description') candidate
38	        from public.source_transactions src
39	        join public.transaction_sources link on link.source_transaction_id=src.id
40	        join public.transactions t on t.id=link.transaction_id
41	        where src.workspace_id=p_workspace_id and src.import_id<>p_import_id and src.external_id=item->'row'->>'externalId'
42	          and t.workspace_id=p_workspace_id and t.account_id=(item->>'accountId')::uuid and t.currency_code=item->'row'->>'currencyCode'
43	      ) indexed_candidates
44	      limit 1001
45	    ) bounded;
46	    if jsonb_array_length(candidates)>1000 then raise exception 'Import candidate limit exceeded; review the overlapping history' using errcode='22023'; end if;
47	    result:=result||jsonb_build_array(jsonb_build_object('rowNumber',item->'row'->'rowNumber','hasExternalId',item->'row'->>'externalId' is not null,'status',item->'row'->'status','candidates',candidates)
48	      ||case when occurrences ? (item->'row'->>'rowNumber') then jsonb_build_object('occurrence',occurrences->(item->'row'->>'rowNumber')) else '{}'::jsonb end);
49	  end loop;
50	  return result;
51	end;
52	$$;
53	
54	create or replace function public.ingest_import_batch(p_import_id uuid,p_workspace_id uuid,p_run_version integer,p_offset integer,p_decisions jsonb) returns jsonb
55	language plpgsql security definer set search_path='' as $$
56	declare total integer; item jsonb; decision jsonb; payload jsonb; decisions_count integer:=0; complete_window boolean; by_occurrence boolean;
57	begin
58	  if jsonb_typeof(p_decisions) is distinct from 'array' or jsonb_array_length(p_decisions)>250 or octet_length(p_decisions::text)>100000 then raise exception 'Invalid import batch decisions' using errcode='22023'; end if;
59	  -- Lock all existing canonical targets before the import, preserving correction
60	  -- lock order even when a retry finds an already linked source.
61	  perform t.id from public.transactions t where t.workspace_id=p_workspace_id and
62	    (t.id in(select (value->>'transactionId')::uuid from jsonb_array_elements(p_decisions) where value->>'action'='matched') or
63	    t.id in(select l.transaction_id from public.transaction_sources l join public.source_transactions s on s.id=l.source_transaction_id where s.import_id=p_import_id and s.workspace_id=p_workspace_id and s.row_number>=p_offset+2 and s.row_number<p_offset+252)) order by t.id for update;
64	  total:=public.read_import_stage(p_import_id,p_workspace_id,p_run_version);
65	  if total is null or p_offset is null or p_offset<0 or p_offset%250<>0 or p_offset>=total then raise exception 'Invalid normalized batch offset' using errcode='22023'; end if;
66	  complete_window:=coalesce((select (mapping->>'completeWindow')::boolean from public.imports where id=p_import_id),false);
67	  -- Multiple accounts always acquire their overlap locks in the same order.
68	  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_workspace_id::text||':'||a.id::text,0)) from public.accounts a where a.id in
69	    (select (value->>'accountId')::uuid from public.import_staging s,jsonb_array_elements(s.rows) with ordinality r(value,n) where s.import_id=p_import_id and n>p_offset and n<=p_offset+250 and not (value->>'excluded')::boolean) order by a.id;
70	  for item in select value from public.import_staging s,jsonb_array_elements(s.rows) with ordinality r(value,n) where s.import_id=p_import_id and n>p_offset and n<=p_offset+250 loop
71	    if (item->>'excluded')::boolean then
