import { applicationMigrationSql } from "../supabase/tests/migration-replay.mjs";
import { randomUUID, createHash } from "node:crypto";
import { readFileSync, readdirSync } from "node:fs";
import postgres from "postgres";
process.loadEnvFile(".env.qa");
const [mode = "plain", total = 10000] = process.argv.slice(2);
const notices = [];
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: n => notices.push(n.message), connection: { application_name: "issue188-measure", statement_timeout: "600s" } });
const schema = `issue188_${randomUUID().replaceAll("-", "")}`;
const isolated = text => text.replace(/\bpublic\./g, `${schema}.`).replace(/\bauth\.users\b/g, `${schema}.auth_users`);
const rollback = new Error("rollback");
try {
  await db.begin(async tx => {
    await tx.unsafe(`create schema ${schema}; create table ${schema}.auth_users(id uuid primary key,email text); grant usage on schema ${schema} to authenticated,service_role`);
    for (const file of readdirSync("supabase/migrations").filter(f => f.endsWith(".sql")).sort()) {
      let text = readFileSync(`supabase/migrations/${file}`, "utf8");
      text = applicationMigrationSql(file, text, schema).replace(/^create extension if not exists pgcrypto;\s*/i, "");
      await tx.unsafe(isolated(text));
    }
    const app = (strings, ...values) => tx.unsafe(isolated(strings.reduce((t, p, i) => t + p + (i < values.length ? `$${i + 1}` : ""), "")), values);
    const actor = randomUUID();
    await app`insert into auth.users(id,email) values(${actor},${`qa-188-${actor}@example.invalid`})`;
    const [{ id: workspace }] = await app`select id from public.workspaces where owner_id=${actor}`;
    const imported = randomUUID(), account = randomUUID(), source = randomUUID(), n = Number(total);
    const csv = ["Date,Description,Amount", ...Array.from({ length: n }, (_, i) => `2026-10-01,Synthetic ${i},-1.01`)].join("\n");
    const hash = createHash("sha256").update(csv).digest("hex"), accountName = `Bounded ${n}`;
    await app`insert into public.imports(id,workspace_id,filename,storage_path,file_hash,status,total_rows,mapping) values(${imported},${workspace},'synthetic.csv',${workspace + "/synthetic.csv"},${hash},'queued',${n},'{"rowContractVersion":"normalized-row-v1"}'::jsonb)`;
    await app`select public.prepare_import_route(${imported},${workspace},1,${account},${source},${accountName},'EUR',${n})`;
    const [{ rows }] = await app`select jsonb_agg(jsonb_build_object('accountId',${account}::uuid,'excluded',false,'row',jsonb_build_object('accountName',${accountName}::text,'sourceId',public.stable_import_uuid(${imported}::text||':row:'||n),'balanceId',public.stable_import_uuid(${imported}::text||':balance:'||n),'rowNumber',n,'originalRow',jsonb_build_object('Amount','-1.01','Description','Synthetic '||(n-2)),'postedOn','2026-10-01','description','Synthetic '||(n-2),'amountMinor','-101','currencyCode','EUR','status','posted','kind','ordinary','reviewReasons','[]'::jsonb))) as rows from generate_series(2,${n + 1}) n`;
    await tx.unsafe(`select ${schema}.stage_import_rows($1::uuid,$2::uuid,1,$3::text,(select mapping from ${schema}.imports where id=$1::uuid),(select route_accounts from ${schema}.imports where id=$1::uuid),(select source_id from ${schema}.imports where id=$1::uuid),$4::jsonb)`, [imported, workspace, hash, rows]);
    if (mode === "analyze") await tx.unsafe(`analyze ${schema}.transactions; analyze ${schema}.source_transactions; analyze ${schema}.transaction_sources; analyze ${schema}.import_staging`);
    const explainBatches = new Set([0, Math.floor((n - 1) / 250)]);
    const timings = [];
    for (let offset = 0; offset < n; offset += 250) {
      const batch = offset / 250, explain = mode === "explain" && explainBatches.has(batch);
      if (explain) { await tx.unsafe(`load 'auto_explain'; set local auto_explain.log_min_duration=0; set local auto_explain.log_analyze=on; set local auto_explain.log_buffers=on; set local auto_explain.log_nested_statements=on; set local auto_explain.log_level=notice; set local auto_explain.log_format=json`); notices.length = 0; }
      let t = performance.now();
      const [{ result: candidates }] = await tx.unsafe(`select ${schema}.import_batch_candidates($1::uuid,$2::uuid,1,$3::integer) as result`, [imported, workspace, offset]);
      const candMs = performance.now() - t; t = performance.now();
      const candNotices = explain ? notices.splice(0) : [];
      await tx.unsafe(`select ${schema}.ingest_import_batch($1::uuid,$2::uuid,1,$3::integer,$4::jsonb)`, [imported, workspace, offset, candidates.map(r => ({ rowNumber: r.rowNumber, action: "new" }))]);
      const ingestMs = performance.now() - t;
      const ingestNotices = explain ? notices.splice(0) : [];
      if (explain) {
        await tx.unsafe(`set local auto_explain.log_min_duration=-1`);
        for (const [label, list] of [["candidates", candNotices], ["ingest", ingestNotices]]) {
          const agg = new Map();
          for (const m of list) { const j = m.indexOf("{"); if (j < 0) continue; let p; try { p = JSON.parse(m.slice(j)); } catch { continue; } const q = p["Query Text"].replace(/\s+/g, " ").slice(0, 160); const a = agg.get(q) ?? { calls: 0, ms: 0, sharedHit: 0, sharedRead: 0, plan: p.Plan }; a.calls++; a.ms += p.Plan["Actual Total Time"]; a.sharedHit += p.Plan["Shared Hit Blocks"] ?? 0; a.sharedRead += p.Plan["Shared Read Blocks"] ?? 0; agg.set(q, a); }
          const top = [...agg.entries()].sort((x, y) => y[1].ms - x[1].ms).slice(0, 6);
          console.log(`--- batch ${batch + 1} ${label} (${label === "candidates" ? candMs.toFixed(0) : ingestMs.toFixed(0)} ms wall)`);
          for (const [q, a] of top) console.log(`${a.ms.toFixed(1)}ms calls=${a.calls} hit=${a.sharedHit} read=${a.sharedRead} :: ${q}`);
        }
      }
      timings.push([candMs, ingestMs]);
    }
    const sum = (from, to) => timings.slice(from, to).reduce((s, [a, b]) => [s[0] + a, s[1] + b], [0, 0]).map(v => v.toFixed(0));
    console.log(`mode=${mode} rows=${n} batches=${timings.length}`);
    for (const i of [0, 1, 9, 19, 29, timings.length - 1]) if (timings[i]) console.log(`batch ${i + 1}: candidates ${timings[i][0].toFixed(0)} ms, ingest ${timings[i][1].toFixed(0)} ms`);
    console.log(`total candidates/ingest ms: ${sum(0, timings.length)}`);
    throw rollback;
  });
} catch (e) { if (e !== rollback) throw e; } finally { await db.end(); }
